import type { CmsBlockSchema } from './schema/cms'
import type { RecordKey } from './schema/common'
import type { BaseComponent, BaseEntry, BaseField } from './schema/components'
import type { PageSchema } from './schema/panel'
import type { BaseColumnSchema, CellSchema } from './schema/table'
import type { BaseWidgetSchema } from './schema/widgets'

/*
 * Props of custom components, so an app's component types its PHP class's
 * `getSchemaProps()` (generated by `php artisan alfakit:types`, or written by hand):
 *
 * ```tsx
 * export default function ColorWheel({ component }: FieldProps<{ swatches: string[] }>) {}
 * ```
 */

/** A custom field (`fields/*`): `component` is the field schema plus `getSchemaProps()`. */
export interface FieldProps<T extends object = object> {
  component: BaseField & T
}

/** A custom infolist entry (`entries/*`): `component.state` is the value. */
export interface EntryProps<T extends object = object> {
  component: BaseEntry & T
}

/** A custom layout component (`components/*`): render its children with `<SchemaChildren>`. */
export interface SchemaComponentProps<T extends object = object> {
  component: BaseComponent & T
}

/**
 * A custom column cell (`columns/*`): `column` carries `getSchemaProps()`, `cell` the
 * record's `state` and `getCellProps()`.
 */
export interface ColumnProps<TColumn extends object = object, TCell extends object = object> {
  column: BaseColumnSchema & TColumn
  cell: CellSchema & TCell
  recordKey: RecordKey
  token: string
  component: string
}

/**
 * A custom widget (`widgets/*`): a `$component` widget gets its `getViewData()` as props,
 * every widget its schema (`getSchemaProps()` merged in) as `widget`.
 */
export type WidgetProps<
  TProps extends object = object,
  TWidget extends object = object,
> = TProps & {
  widget: BaseWidgetSchema & TWidget
}

/** A custom page (`pages/*`): its `getViewData()` as props and the page schema. */
export type PageComponentProps<TProps extends object = object> = TProps & { page: PageSchema }

/** A CMS block (`blocks/*`). */
export interface BlockProps<TData extends object = Record<string, unknown>> {
  block: CmsBlockSchema<TData>
  data: TData
}
